{"implementation":"def solve(case):
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    # Build node dict and children map
    node_dict = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        if n['parent'] is not None:
            children.setdefault(n['parent'], []).append(n['id'])
    # All node ids
    all_ids = set(n['id'] for n in nodes)
    # Initialize global symbol counts (original)
    global_symbol_counts = {}
    for n in nodes:
        global_symbol_counts[n['symbol']] = global_symbol_counts.get(n['symbol'], 0) + 1

    removed_ids = set()
    removed_order = []

    # Sort by depth descending, then id ascending
    nodes_sorted = sorted(nodes, key=lambda n: (-n['depth'], n['id']))

    for node in nodes_sorted:
        nid = node['id']
        if nid in removed_ids:
            continue
        # Conditions:
        # 1) removable
        if not node['removable']:
            continue
        # 2) not root
        if node['parent'] is None:
            continue
        # 3) not a required symbol
        if node['symbol'] in required_symbols:
            continue
        # 4) no retained children (any child not yet removed)
        has_child_retained = False
        for cid in children.get(nid, []):
            if cid not in removed_ids:
                has_child_retained = True
                break
        if has_child_retained:
            continue

        # Compute current subtree of this node (including itself and all non-removed descendants)
        subtree_ids = set()
        stack = [nid]
        while stack:
            cur = stack.pop()
            if cur in subtree_ids:
                continue
            subtree_ids.add(cur)
            for cid in children.get(cur, []):
                if cid not in removed_ids:
                    stack.append(cid)

        # Compute current symbol counts (only nodes not yet removed)
        current_counts = {}
        for n in nodes:
            if n['id'] not in removed_ids:
                sym = n['symbol']
                current_counts[sym] = current_counts.get(sym, 0) + 1

        # Compute symbol counts in subtree
        subtree_counts = {}
        for sid in subtree_ids:
            sym = node_dict[sid]['symbol']
            subtree_counts[sym] = subtree_counts.get(sym, 0) + 1

        # Check required symbols still present after removal
        can_remove = True
        for req_sym in required_symbols:
            if current_counts.get(req_sym, 0) - subtree_counts.get(req_sym, 0) < 1:
                can_remove = False
                break

        if can_remove:
            removed_ids.update(subtree_ids)
            removed_order.append(nid)

    retained_ids = sorted(all_ids - removed_ids)
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_ids
    }"}
